with prev_events as (select *, lag(txn_time) over (partition by account_id order by txn_time asc, id asc) as prev_txn_time from transactions), with_gaps as (select *, case when prev_txn_time is null or txn_time > prev_txn_time + interval '7' day then 1 else 0 end as is_new_burst from prev_events), sessions_transactions as (select id, account_id, txn_type, txn_time, merchant, sum(is_new_burst) over (partition by account_id order by txn_time asc, id asc rows between unbounded preceding and current row) as island_id from with_gaps) select s.id, s.account_id, s.txn_type, s.merchant, s.island_id, case when merchant rlike '^(Shell|7-Eleven)$' then 'EXTENDED' else 'PRIORITY' end as merchant_zone, (select max(t2.amount) from transactions t2 where t2.account_id = s.account_id) as max_transaction_amount from sessions_transactions s order by merchant asc;
